  "keep_that_well_clear_of_my_rigging":["Halt das ja von meinem Tauwerk fern.","0s4m228"],
  "i_keep_my_reckoning_in_knots":["Meine Rechnung führe ich in Knoten auf einer Schnur. Sie hat sich noch nie geirrt.","0vl58qf"],
  "stow_it_friend":["Verstau es, Freund. Ein Kai ist kein Ort, um Dinge abzulegen.","0sfusa4"],
  "linen_i":["Leinen? Ich fahre Wolle und Öl, Freund. Segeltuch habe ich, und kein sauberer Faden daran.","0uq105m"],
  "cloth_for_a_sling":["Tuch für eine Schlinge? Bei der Achterleine liegt ein Haufen altes Segel. Nimm dir davon, was du willst.","1i7hvug"],
  "where_are_you_bound_shipmaster":["Wohin fährst du, Schiffsherr?","0ykqzty"],
